class Solution {
public:
    vector<int> constructDistancedSequence(int n) {
        int len = 2 * n - 1;
        vector<int> ans(len, 0);
        vector<bool> used(n + 1, false);
        backtrack(ans, used, 0, n);
        return ans;
    }
private:
    bool backtrack(vector<int>& ans, vector<bool>& used, int pos, int n) {
        int len = (int)ans.size();
        if (pos == len) return true;
        if (ans[pos] != 0) return backtrack(ans, used, pos + 1, n);
        for (int v = n; v >= 1; v--) {
            if (used[v]) continue;
            if (v == 1) {
                ans[pos] = 1;
                used[1] = true;
                if (backtrack(ans, used, pos + 1, n)) return true;
                used[1] = false;
                ans[pos] = 0;
            } else {
                int p2 = pos + v;
                if (p2 >= len || ans[p2] != 0) continue;
                ans[pos] = v;
                ans[p2] = v;
                used[v] = true;
                if (backtrack(ans, used, pos + 1, n)) return true;
                used[v] = false;
                ans[pos] = 0;
                ans[p2] = 0;
            }
        }
        return false;
    }
};
